<?php $pageTitle='Collection Management';require '../includes/admin-header.php';$pdo=db();$action=$_GET['action']??'';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='add'){$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)')->execute([trim($_POST['name']),trim($_POST['description'])]);flash('success','Collection added.');}if(($_POST['action']??'')==='edit'){$pdo->prepare('UPDATE categories SET name=?,description=? WHERE id=?')->execute([trim($_POST['name']),trim($_POST['description']),(int)$_POST['id']]);flash('success','Collection updated.');}go('admin/categories.php');}if($action==='delete'&&$id){$q=$pdo->prepare('SELECT COUNT(*) FROM products WHERE category_id=?');$q->execute([$id]);if($q->fetchColumn())flash('warning','This collection contains products and cannot be deleted.');else{$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('success','Collection deleted.');}go('admin/categories.php');}$categories=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll(); ?><div class="row g-4"><div class="col-lg-4"><form method="post" class="card card-body"><input type="hidden" name="action" value="add"><h5>Add collection</h5><input class="form-control mb-2" name="name" placeholder="Collection name" required><textarea class="form-control mb-3" name="description" placeholder="Description"></textarea><button class="btn btn-dark">Add collection</button></form></div><div class="col-lg-8"><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Collection</th><th>Description</th><th>Products</th><th></th></tr></thead><tbody><?php foreach($categories as $c): ?><tr><td><?=e($c['name'])?></td><td><?=e($c['description'])?></td><td><?=$c['product_count']?></td><td><a class="btn btn-sm btn-outline-danger" data-confirm="Delete this empty collection?" href="categories.php?action=delete&id=<?=$c['id']?>">Delete</a></td></tr><?php endforeach ?></tbody></table></div></div></div><?php require '../includes/admin-footer.php'; ?>
